package com.example.seeforyou.localization

import java.util.Locale

/** Local phrases; no network translation. Native-speaker review is still needed. */
class PhraseBook(tag: String = "en-IN") {
    val language = Locale.forLanguageTag(tag).language.let { if (it in listOf("hi", "kn")) it else "en" }
    private val column = when (language) { "hi" -> 1; "kn" -> 2; else -> 0 }
    fun text(key: String, vararg args: Any): String {
        val pattern = phrases.getValue(key)[column]
        return if (args.isEmpty()) pattern else String.format(Locale.forLanguageTag(language), pattern, *args)
    }
    fun objectName(label: String): String = objects[label]?.get(column) ?: text("unknown_object")
    fun maneuver(type: Int, road: String, original: String, exit: Int = 0): String {
        if (language == "en") return original
        var instruction = if (type in 0..13) text("turn_" + type) else text("direction_unknown")
        if (type == 11) {
            val heading = Regex("\\b(northeast|northwest|southeast|southwest|north|south|east|west)\\b",
                RegexOption.IGNORE_CASE).find(original)?.value?.lowercase(Locale.ROOT)
            if (heading != null) instruction = text("depart_heading", text("heading_" + heading))
        }
        if (type in listOf(7, 8) && exit > 0) instruction += ". " + text("roundabout_exit", exit)
        return if (road.isNotBlank() && road != "-") text("road_instruction", instruction, road) else instruction
    }
