            "resume_speech" to listOf("Resume speech", "बोलना शुरू करें", "ಮಾತು ಮುಂದುವರಿಸಿ"),
            "quiet_ready" to listOf("Quiet mode. Tap Describe to hear what the camera sees.", "शांत मोड। कैमरे में दिख रही चीज़ें सुनने के लिए वर्णन दबाएँ।", "ನಿಶ್ಶಬ್ದ ಮೋಡ್. ಕ್ಯಾಮೆರಾದಲ್ಲಿ ಕಾಣುವ ವಸ್ತುಗಳನ್ನು ಕೇಳಲು ವಿವರಣೆ ಒತ್ತಿ."),
